class OrchestratorRoute:
    """
    String constants for orchestrator graph edges.
    Using a class of constants (rather than raw strings) means a typo
    becomes an AttributeError at import time rather than a silent wrong-
    branch at runtime.
    """
    EXECUTE_TASK  = "execute_task"    # â†’ run the subgraph for current task
    NEXT_TASK     = "next_task"       # â†’ advance index and loop
    BUNDLE        = "bundle"          # â†’ all tasks done, build bundle
    FAIL          = "fail"            # â†’ unrecoverable error, abort run
    APPROVE       = "request_approval"# â†’ push approval_request over HITL


class TaskRoute:
    """String constants for task subgraph edges."""
    TO_CRITIC     = "to_critic"       # developer â†’ critic (Reflection)
    TO_REVIEWERS  = "to_reviewers"    # developer/critic â†’ reviewer fan-out
    RETRY         = "retry"           # reduce_verdicts â†’ developer (retry)
    FINALIZE      = "finalize"        # reduce_verdicts â†’ finalize_task (pass)
    FAIL          = "fail"            # retry cap hit â†’ finalize as failed



